const { useEffect, useRef, useState } = React;

const EVENT_COLORS = { beforetoggle: "purple", toggle: "blue", cancel: "orange", close: "green" };

const MethodButton = ({ children, ...props }) => (
  <ui.Button variant="secondary" size="sm" {...props}>
    <span className="font-tau-mono">{children}</span>
  </ui.Button>
);

const Row = ({ label, children }) => (
  <div className="flex min-w-0 items-center justify-between gap-3">
    <span className="shrink-0 font-tau-mono text-tau-sm text-ink-3">{label}</span>
    <span className="min-w-0 truncate font-tau-mono text-tau-sm text-ink-1">{children}</span>
  </div>
);

const Component = () => {
  const rootRef = useRef(null);
  const dialogRef = useRef(null);
  const timerRef = useRef(0);
  const optionsRef = useRef({});
  const [backdropClose, setBackdropClose] = useState(true);
  const [blockCancel, setBlockCancel] = useState(false);
  const [state, setState] = useState({ open: false, modal: false, returnValue: "" });
  const [focusBack, setFocusBack] = useState(null);
  const [clicks, setClicks] = useState(0);
  const [log, setLog] = useState([]);
  optionsRef.current = { backdropClose, blockCancel };

  const read = () => {
    const dialog = dialogRef.current;
    let modal = false;
    try {
      modal = dialog.matches(":modal");
    } catch {}
    setState({ open: dialog.open, modal, returnValue: dialog.returnValue ?? "" });
  };
  const push = (name, detail) => setLog(list => [{ id: Date.now() + Math.random(), name, detail }, ...list].slice(0, 6));

  useEffect(() => {
    const dialog = dialogRef.current;
    const handleBeforeToggle = event => push("beforetoggle", `${event.oldState} → ${event.newState}`);
    const handleToggle = event => {
      push("toggle", `${event.oldState} → ${event.newState}`);
      read();
    };
    const handleCancel = event => {
      if (optionsRef.current.blockCancel) event.preventDefault();
      push("cancel", optionsRef.current.blockCancel ? "已 preventDefault" : "放行");
    };
    const handleClose = () => {
      push("close", `returnValue："${dialog.returnValue}"`);
      read();
      // 焦点恢复发生在关闭步骤之后，下一轮再读
      clearTimeout(timerRef.current);
      timerRef.current = setTimeout(() => {
        const active = document.activeElement;
        setFocusBack(rootRef.current?.contains(active) ? active.textContent.trim() || active.tagName.toLowerCase() : "块外元素");
      }, 0);
    };
    const handleClick = event => {
      if (!optionsRef.current.backdropClose || !dialog.matches?.(":modal")) return;
      const rect = dialog.getBoundingClientRect();
      const outside = event.clientX < rect.left || event.clientX > rect.right || event.clientY < rect.top || event.clientY > rect.bottom;
      if (outside) dialog.close("backdrop");
    };
    dialog.addEventListener("beforetoggle", handleBeforeToggle);
    dialog.addEventListener("toggle", handleToggle);
    dialog.addEventListener("cancel", handleCancel);
    dialog.addEventListener("close", handleClose);
    dialog.addEventListener("click", handleClick);
    return () => {
      clearTimeout(timerRef.current);
      dialog.removeEventListener("beforetoggle", handleBeforeToggle);
      dialog.removeEventListener("toggle", handleToggle);
      dialog.removeEventListener("cancel", handleCancel);
      dialog.removeEventListener("close", handleClose);
      dialog.removeEventListener("click", handleClick);
      if (dialog.open) dialog.close?.();
    };
  }, []);

  const open = method => {
    const dialog = dialogRef.current;
    if (dialog.open) dialog.close?.();
    setFocusBack(null);
    if (typeof dialog[method] === "function") dialog[method]();
    else dialog.setAttribute("open", "");
    push(`${method}()`, "调用");
    read();
  };
  const close = value => dialogRef.current.close?.(value);
  const requestClose = () => {
    const dialog = dialogRef.current;
    if (typeof dialog.requestClose === "function") dialog.requestClose("request");
    else push("requestClose()", "当前浏览器不支持");
  };

  return (
    <div ref={rootRef} className="@container flex flex-col gap-3">
      <style>{`
        @scope {
          .cb-dialog:not(:modal) { position: absolute; }
          .cb-dialog::backdrop {
            background: var(--tau-overlay);
            backdrop-filter: blur(2px);
          }
          .cb-row { animation: cb-dialog-row 320ms var(--tau-ease-out) both; }
          @media (prefers-reduced-motion: reduce) {
            .cb-row { animation: none; }
          }
        }
        @keyframes cb-dialog-row {
          from { opacity: 0; transform: translateY(4px); }
          to { opacity: 1; transform: none; }
        }
      `}</style>
      <div className="grid gap-3 @lg:grid-cols-[minmax(0,1fr)_minmax(240px,38%)]">
        <div className="relative h-[240px] min-w-0 rounded-tau-md border border-line-1 p-3">
          <div className="flex flex-col gap-2">
            <span className="text-tau-sm text-ink-3">页面内容</span>
            <ui.Button variant="soft" size="sm" className="self-start" onClick={() => setClicks(count => count + 1)}>
              页面上的按钮
            </ui.Button>
            <span className="font-tau-mono text-tau-sm text-ink-3">点击：{clicks} 次</span>
          </div>
          <dialog
            ref={dialogRef}
            className="cb-dialog inset-0 m-auto h-fit w-[min(320px,88%)] rounded-tau-md border border-line-1 bg-surface p-0 text-ink-1 shadow-lift"
          >
            <div className="flex flex-col gap-3 p-4">
              <div className="flex items-center gap-2">
                <span className="text-tau-body text-ink-1">{state.modal ? "模态对话框" : "非模态对话框"}</span>
                <ui.Tag color={state.modal ? "blue" : "gray"}>{state.modal ? ":modal" : "show() 打开"}</ui.Tag>
              </div>
              <p className="m-0 text-tau-meta text-ink-2">
                {state.modal ? "页面其余部分已不可交互，按 Esc 触发 cancel。" : "仍在文档流中，左上角的页面按钮照样能点。"}
              </p>
              <div className="flex flex-wrap justify-end gap-2">
                <ui.Button variant="ghost" size="sm" onClick={requestClose}>
                  <span className="font-tau-mono">requestClose()</span>
                </ui.Button>
                <ui.Button variant="secondary" size="sm" onClick={() => close("cancel")}>
                  取消
                </ui.Button>
                <ui.Button variant="primary" size="sm" onClick={() => close("confirm")}>
                  确认
                </ui.Button>
              </div>
            </div>
          </dialog>
        </div>
        <div className="flex min-w-0 flex-col gap-2 rounded-tau-md border border-line-1 p-3">
          <div className="flex flex-col gap-1 rounded-tau-sm bg-hover px-2.5 py-2">
            <Row label="open">{String(state.open)}</Row>
            <Row label=":modal">{String(state.modal)}</Row>
            <Row label="returnValue">"{state.returnValue}"</Row>
            <Row label="焦点回到">{focusBack ?? "—"}</Row>
          </div>
          <span className="text-tau-sm text-ink-3">事件（新的在上）</span>
          {log.length ? (
            <ol className="m-0 flex list-none flex-col gap-1.5 p-0">
              {log.map(entry => (
                <li key={entry.id} className="cb-row flex min-w-0 items-center gap-2">
                  {EVENT_COLORS[entry.name] ? (
                    <ui.Tag color={EVENT_COLORS[entry.name]} className="shrink-0">
                      {entry.name}
                    </ui.Tag>
                  ) : (
                    <code className="shrink-0 rounded-tau-sm bg-hover px-1.5 py-0.5 font-tau-mono text-tau-tiny text-ink-2">
                      {entry.name}
                    </code>
                  )}
                  <span className="min-w-0 truncate font-tau-mono text-tau-sm text-ink-3">{entry.detail}</span>
                </li>
              ))}
            </ol>
          ) : (
            <p className="m-0 text-tau-meta text-ink-3">分别用 show() 与 showModal() 打开</p>
          )}
        </div>
      </div>
      <div className="flex flex-wrap items-center gap-x-6 gap-y-3">
        <div className="flex items-center gap-2">
          <MethodButton onClick={() => open("show")}>show()</MethodButton>
          <MethodButton onClick={() => open("showModal")}>showModal()</MethodButton>
        </div>
        <ui.Switch checked={backdropClose} onCheckedChange={setBackdropClose} label="点击遮罩关闭" size="sm" />
        <ui.Switch checked={blockCancel} onCheckedChange={setBlockCancel} label="cancel 中阻止关闭" size="sm" />
      </div>
    </div>
  );
};
